        MutasiModel("H001", "Tablet Xiaomi Pad 5", "Alasan: Layar pecah parah & mati total akibat terjatuh", "18 Mei 2026", "https://www.static-src.com/wcsstore/Indraprastha/images/catalog/full/catalog-image/MTA-181198703/xiaomi_xiaomi_redmi_pad_se_8-7_-4-128gb-_-_layar_8-7-_perlindungan_mata_-_refresh_rate_90hz_-_baterai_6650mah_-_prosesor_octa-core_-official_store-_full01_o97vuc7y.jpg"),
        MutasiModel("H002", "Harddisk External 1TB", "Alasan: Bad sector kronis, data tidak terbaca lagi", "16 Mei 2026", "data:image/jpeg;base64,"),
        MutasiModel("H003", "Kamera Canon EOS 1300D", "Alasan: Sensor jamuran berat & biaya perbaikan terlalu mahal", "14 Mei 2026", "https://megakamera.com/wp-content/uploads/2021/05/Canon-EOS-M200-Mirrorless-Digital-Camera-with-15-45mm-Black-1.jpg"),
        MutasiModel("H004", "Vacuum Cleaner Philips", "Alasan: Dinamo mesin terbakar / korsleting arus pendek", "11 Mei 2026", "data:image/jpeg;base64,"),
        MutasiModel("H005", "Kursi Gaming Razer", "Alasan: Struktur hidrolik patah dan kulit jok mengelupas habis", "09 Mei 2026", "data:image/jpeg;base64,"),
        MutasiModel("H006", "Smartphone Samsung A52", "Alasan: Terendam air banjir, IC Power rusak permanen", "07 Mei 2026", "https://m.media-amazon.com/images/I/81-nNnxa6VS.jpg"),
        MutasiModel("H007", "Blender Philips HR2115", "Alasan: Masa umur ekonomis habis & gear pemutar aus", "04 Mei 2026", "https://www.saletronik.com/wp-content/uploads/2022/06/a2aead511ec44c6f8417ad1e014e0bc7.webp"),
        MutasiModel("H008", "Keyboard Mechanical", "Alasan: Terguyur kopi panas, jalur PCB sirkuit korosi", "02 Mei 2026", "https://alhasanah.or.id/wp-content/uploads/2022/09/Al-Hasanah-Keyboard-Mechanical-1.png"),
