    )

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        // 2. Ubah inflate agar View Binding aktif dengan benar
        _binding = FragmentPenghapusanBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        // 3. Inisialisasi MutasiAdapter dengan data list di atas
        val adapter = MutasiAdapter(penghapusanList) { selectedItem ->
            Toast.makeText(requireContext(), "Melihat Alasan: ${selectedItem.assetName}", Toast.LENGTH_SHORT).show()
        }

        // 4. Pasang adapter ke RecyclerView (Memperbaiki error garis merah sebelumnya)
        binding.rvPenghapusan.apply {
            layoutManager = GridLayoutManager(requireContext(), 2)
            this.adapter = adapter
        }
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}